∀ (d n : ℕ) (β : ℝ),
  2 ≤ n →
    have M := Fintype.card ((j : ↥(CausalSmith.Stat.WeakOverlap.meshIndices d n β)) × (Fin d → Fin (2 ^ ↑j)) × (Fin d → Fin (CausalSmith.Stat.WeakOverlap.polynomialDegree β + 1)));
    have s := Real.log (2 * (↑M + 1) * ↑n ^ 2);
    0 < s ∧ 2 * ↑M * Real.exp (-s) ≤ ↑n ^ (-2)

