∀ (m : MeasureTheory.Measure Bool) [MeasureTheory.SFinite m] (B : ℝ) (p : Bool → ℝ) (hp : Measurable p),
  (∀ (a : Bool), p a ∈ Set.Icc 0 1) →
    have kS := { toFun := fun a => CausalSmith.Stat.WeakOverlap.scaledBernoulli B (p a), measurable' := measurable_of_finite fun a => CausalSmith.Stat.WeakOverlap.scaledBernoulli B (p a) };
    have kB := Causalean.Mathlib.InformationTheory.commonStatisticBernoulliKernel p hp;
    m.compProd kS = MeasureTheory.Measure.map (Prod.map id fun y => B * y) (m.compProd kB)

